cd ~/restaurant-inventory && cat > count.html <<'EOF'
<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Line Count</title>
<style>
body{font-family:sans-serif;margin:0;padding:12px;background:#f7f7f2}
h1{font-size:28px;margin:8px 0}
.item{display:flex;align-items:center;justify-content:space-between;background:#fff;border-radius:12px;padding:10px;margin:10px 0;box-shadow:0 1px 3px #0002}
.name{font-size:26px;font-weight:600;flex:1}
.count{font-size:32px;min-width:90px;text-align:center}
button{font-size:34px;width:96px;height:96px;border:0;border-radius:16px;margin-left:8px;background:#2b7a4b;color:#fff}
button.minus{background:#a33}
.bar{position:sticky;bottom:0;background:#fff;padding:10px;text-align:center}
.save{font-size:28px;padding:20px 30px;border-radius:14px;border:0;background:#245;color:#fff}
</style></head><body>
<h1>Count stock</h1>
<div id="items"></div>
<div class="bar"><button class="save" onclick="exportCounts()">Done: save counts</button></div>
<script>
const ITEMS = [["Tomatoes (lb)",0],["Rice (lb)",0],["Flour (case)",0],["Chicken thighs (lb)",0]];
let counts = JSON.parse(localStorage.getItem("counts") || "null") || Object.fromEntries(ITEMS.map(([n])=>[n,0]));
function step(name, d){ counts[name] = Math.max(0, +(counts[name] + d).toFixed(2)); localStorage.setItem("counts", JSON.stringify(counts)); render(); }
function render(){
  document.getElementById("items").innerHTML = ITEMS.map(([n,_])=>`
    <div class="item"><div class="name">${n}</div>
    <button class="minus" onclick='step(${JSON.stringify(n)}, -1)'>&minus;</button>
    <div class="count">${counts[n]}</div>
    <button onclick='step(${JSON.stringify(n)}, 1)'>+</button></div>`).join("");
}
function exportCounts(){
  const lines = ["item,count"].concat(Object.entries(counts).map(([k,v])=>`${k},${v}`));
  const blob = new Blob([lines.join("\n")], {type:"text/csv"});
  const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = "counts.csv"; a.click();
}
render();
</script></body></html>
EOF
